import sys

class Solution:
    @staticmethod
    def countOfSubstrings(S: str, K: int) -> int:
        n = len(S)
        if K > n:
            return 0
        if K == 1:
            return 0

        freq = [0] * 26
        distinct = 0

        for i in range(K):
            idx = ord(S[i]) - ord('a')
            if freq[idx] == 0:
                distinct += 1
            freq[idx] += 1

        count = 0
        if distinct == K - 1:
            count += 1

        for i in range(K, n):
            out_idx = ord(S[i - K]) - ord('a')
            freq[out_idx] -= 1
            if freq[out_idx] == 0:
                distinct -= 1

            in_idx = ord(S[i]) - ord('a')
            if freq[in_idx] == 0:
                distinct += 1
            freq[in_idx] += 1

            if distinct == K - 1:
                count += 1

        return count

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    S = input_data[0]
    K = int(input_data[1])

    result = Solution.countOfSubstrings(S, K)
    print(result)

if __name__ == "__main__":
    main()
